/*
 Instagram trend taramasi icin kategori / hashtag listesi.
 ONEMLI: approvedOwners listesine SADECE videolarini YouTube'da aynen
 paylasmaya (GORSel + SES) lisans/izin almis oldugunuz hesaplari yazin.
 Liste bosken otomatik yukleme yapilmaz.
*/
const approvedOwners = [];
const hashtags = ['aivideo','aianimation','funnyvideos','satisfying','cuteanimals','viralreels'];
return [{json:{approvedOwners,hashtags,minViews:2000000,withinDays:4}}];

const cfg=$('02 Tarama konulari ve yetkili hesaplar').first().json;
const cutoff=Date.now()-cfg.withinDays*86400000;
const approved=new Set(cfg.approvedOwners.map(x=>String(x).replace(/^@/,'').toLowerCase()));
const db=$getWorkflowStaticData('global');
const uploaded=new Set(Array.isArray(db.uploadedReels)?db.uploadedReels:[]);
const raw=$input.all().map(i=>i.json).flatMap(x=>Array.isArray(x)?x:[x]);
function parseDate(x){const v=x.timestamp||x.takenAt||x.takenAtTimestamp||x.createdAt||x.date;
if(typeof v==='number')return v<10000000000?v*1000:v;return Date.parse(v);}
const identified=raw.filter(x=>typeof x==='object'&&x&&!x.error).map(x=>{
const url=x.url||x.postUrl||x.inputUrl||(x.shortCode?'https://www.instagram.com/reel/'+x.shortCode+'/':null);
const shortCode=x.shortCode||x.shortcode||((url||'').match(/\/reel\/([^/?]+)/)||[])[1];
const user=String(x.ownerUsername||x.owner?.username||x.owner?.userName||'').replace(/^@/,'').toLowerCase();
const views=Number(x.videoPlayCount??x.videoViewCount??x.viewsCount??x.playCount??0);
const time=parseDate(x);
const videoUrl=x.videoUrl||x.video?.url||x.video_url;
const musicType=String(x.musicInfo?.audioType||'').toLowerCase();
return {url,shortCode,user,views,time,videoUrl,musicType,title:String(x.caption||x.text||'').slice(0,100),duration:Number(x.videoDuration||x.video?.duration||0)};
}).filter(x=>x.url&&x.shortCode&&x.user&&x.time>cutoff&&x.time<=Date.now()+60000&&x.views>=cfg.minViews)
.sort((a,b)=>b.views-a.views);
const allowed=identified.filter(x=>approved.has(x.user)&&!uploaded.has(x.shortCode)&&typeof x.videoUrl==='string'&&x.videoUrl.startsWith('https://')&&x.musicType!=='licensed_music'&&(x.duration===0||x.duration<=60));
const selected=allowed[0]||null;
return [{json:{ready:!!selected,approvedOwnersCount:approved.size,qualifiedFound:identified.length,eligibleFound:allowed.length,selected}}];

const posted=$input.first().json;
const id=posted.id||posted.uploadId;
if(!id)throw new Error('YouTube video ID gelmedi. Ayni Reel tekrar yuklenmesin diye sonucu kontrol edin.');
const s=$('04 Son 4 gun 2M ve lisans filtre').first().json.selected;
const db=$getWorkflowStaticData('global');
const history=Array.isArray(db.uploadedReels)?db.uploadedReels:[];
if(!history.includes(s.shortCode))history.push(s.shortCode);
db.uploadedReels=history.slice(-500);
return [{json:{status:'uploaded_public',youtubeUrl:'https://www.youtube.com/watch?v='+id,source:s.url,views:s.views}}];
